import React, { useState } from 'react';
import { CNameInfo, Typography } from '@cloud-materials/common';

const defaultRecord = {
  name: 'nameRecord-正是江南好时节，落花时节又逢君',
  id: 'idRecord-正是江南好时节，落花时节又逢君',
};

export default () => {
  const [record, setRecord] = useState(defaultRecord);

  return (
    <>
      <Typography.Title heading={5}>可编辑、复制，省略情况</Typography.Title>
      这里显示出外框的border用来说明，copy、edit、和后缀的icon会计入CEllipsis省略宽度的计算
      <div style={{ width: 300, border: '1px solid beige', borderRadius: '2px' }}>
        <CNameInfo
          name={record.name}
          id={record.id}
          nameCopyable
          nameEditable
          idCopyable
          onNameEditOk={val => {
            setRecord({ ...defaultRecord, name: val || '-' });
          }}
          nameCEllipsisProps={{ maxWidth: 300 }}
        />
      </div>
      <Typography.Title heading={5}>可编辑、复制，非省略情况</Typography.Title>
      <div style={{ width: 350, border: '1px solid beige', borderRadius: '2px' }}>
        <CNameInfo
          name={record.name}
          id={record.id}
          nameCopyable
          nameEditable
          idCopyable
          onNameEditOk={val => {
            setRecord({ ...defaultRecord, name: val || '-' });
          }}
        />
      </div>
      <Typography.Title heading={5}>可带有校验的编辑使用</Typography.Title>
      <div style={{ width: 300 }}>
        <CNameInfo
          name={record.name}
          id={record.id}
          nameEditable
          onNameEditOk={val => {
            setRecord({ ...defaultRecord, name: val || '-' });
          }}
          nameEditRules={[
            {
              required: true,
              match: new RegExp('^[A-Za-z0-9-]{0,128}$'),
              message: '必填，只能包含字母、数字和中划线，长度不超过128个字符',
            },
          ]}
        />
      </div>
    </>
  );
};

import React from 'react';
import { CNameInfo, useCConfigContext, Typography, Popover, CTag } from '@cloud-materials/common';
import { IconWifiSecurity } from '@arco-design/iconbox-react-ve-o-design';

const defaultRecord = {
  name: 'nameRecord-正是江南好时节，落花时节又逢君',
  id: 'idRecord-正是江南好时节，落花时节又逢君',
};

export default () => {
  const { useCssPrefix } = useCConfigContext();
  const iconCls = useCssPrefix('')`icon`;

  return (
    <>
      <Typography.Title heading={5}>添加CTag后缀或Protect后缀</Typography.Title>
      <div style={{ width: 300 }}>
        <CNameInfo
          name={defaultRecord.name}
          id={defaultRecord.id}
          nameCopyable
          idCopyable
          suffix={
            <Popover content="已开启实例删除保护">
              <IconWifiSecurity className={iconCls} />
            </Popover>
          }
        />
      </div>
      <div style={{ width: 300, marginTop: 20 }}>
        <CNameInfo name={defaultRecord.name} id={defaultRecord.id} nameCopyable idCopyable suffix={<CTag>CTag</CTag>} />
      </div>
      <Typography.Title heading={5}>添加CTag后缀和Protect后缀, 有编辑</Typography.Title>
      <div style={{ width: 200 }}>
        <CNameInfo
          name={defaultRecord.name}
          id={defaultRecord.id}
          nameCopyable
          idCopyable
          nameEditable
          suffix={
            <Popover content="已开启实例删除保护">
              <IconWifiSecurity className={iconCls} />
            </Popover>
          }
        />
      </div>
      <Typography.Title heading={5}>
        不希望未显示的icon占据宽度，当固定宽度时，出现的icon会挤压前置空间
      </Typography.Title>
      <div style={{ width: 258 }}>
        <CNameInfo
          name={defaultRecord.name}
          id={defaultRecord.id}
          nameCopyable
          idCopyable
          nameEditable
          isIconHoverSqueezeWidth
          suffix={
            <Popover content="已开启实例删除保护">
              <IconWifiSecurity className={iconCls} />
            </Popover>
          }
        />
      </div>
      <div style={{ width: 350 }}>
        <CNameInfo
          name={defaultRecord.name}
          id={defaultRecord.id}
          nameCopyable
          idCopyable
          nameEditable
          isIconHoverSqueezeWidth
          suffix={
            <Popover content="已开启实例删除保护">
              <IconWifiSecurity className={iconCls} />
            </Popover>
          }
        />
      </div>
    </>
  );
};

